CREATE TABLE IF NOT EXISTS "user" (id text PRIMARY KEY,name text NOT NULL,email text NOT NULL UNIQUE,"emailVerified" boolean NOT NULL DEFAULT false,image text,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now(),role text NOT NULL DEFAULT 'customer' CHECK(role IN ('customer','admin')),"twoFactorEnabled" boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS "session" (id text PRIMARY KEY,"expiresAt" timestamptz NOT NULL,token text NOT NULL UNIQUE,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now(),"ipAddress" text,"userAgent" text,"userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS session_user_idx ON "session"("userId");
CREATE TABLE IF NOT EXISTS "account" (id text PRIMARY KEY,"accountId" text NOT NULL,"providerId" text NOT NULL,"userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,"accessToken" text,"refreshToken" text,"idToken" text,"accessTokenExpiresAt" timestamptz,"refreshTokenExpiresAt" timestamptz,scope text,password text,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now(),UNIQUE("providerId","accountId"));
CREATE INDEX IF NOT EXISTS account_user ON "account"("userId");
CREATE TABLE IF NOT EXISTS "verification" (id text PRIMARY KEY,identifier text NOT NULL,value text NOT NULL,"expiresAt" timestamptz NOT NULL,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS verification_identifier ON "verification"(identifier);
CREATE TABLE IF NOT EXISTS "twoFactor" (id text PRIMARY KEY,secret text NOT NULL,"backupCodes" text NOT NULL,"userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,verified boolean DEFAULT true,"failedVerificationCount" integer DEFAULT 0,"lockedUntil" timestamptz);
CREATE INDEX IF NOT EXISTS twofactor_user ON "twoFactor"("userId");
CREATE TABLE IF NOT EXISTS "rateLimit" (id text PRIMARY KEY,key text NOT NULL UNIQUE,count integer NOT NULL,"lastRequest" bigint NOT NULL);
ALTER TABLE "member" ADD CONSTRAINT member_user_fk FOREIGN KEY("userId") REFERENCES "user"(id) ON DELETE CASCADE;
CREATE TABLE IF NOT EXISTS orders (id text PRIMARY KEY,organisation_id text REFERENCES "organization"(id),email text NOT NULL,company text NOT NULL,name text NOT NULL,amount bigint NOT NULL CHECK(amount>0),currency text NOT NULL DEFAULT 'gbp',status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid','expired','failed','refunded')),offer text NOT NULL CHECK(offer IN ('savings-sprint','implementation')),proposal_id text REFERENCES records(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),receipt_url text,stripe_session_id text UNIQUE,stripe_payment_id text UNIQUE,checkout_key text NOT NULL UNIQUE,terms_version text NOT NULL,legal_snapshot jsonb NOT NULL,tax_snapshot jsonb NOT NULL,billing jsonb NOT NULL DEFAULT '{}',provider text NOT NULL DEFAULT 'stripe');
CREATE INDEX IF NOT EXISTS orders_email ON orders(email);
CREATE INDEX IF NOT EXISTS orders_org ON orders(organisation_id);
CREATE UNIQUE INDEX IF NOT EXISTS orders_active_proposal ON orders(proposal_id) WHERE status IN ('pending','paid');
CREATE TABLE IF NOT EXISTS payment_events (id text PRIMARY KEY,type text NOT NULL,order_id text REFERENCES orders(id),received_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz);
CREATE TABLE IF NOT EXISTS mail_outbox (id text PRIMARY KEY,to_email text NOT NULL,subject text NOT NULL,text_body text NOT NULL,html_body text,status text NOT NULL DEFAULT 'pending',attempts integer NOT NULL DEFAULT 0,last_error text,created_at timestamptz NOT NULL DEFAULT now(),sent_at timestamptz);
CREATE INDEX IF NOT EXISTS outbox_pending ON mail_outbox(status,created_at);
CREATE TABLE IF NOT EXISTS request_limits (key text PRIMARY KEY,count integer NOT NULL,reset_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS contact_enquiries (id text PRIMARY KEY,name text NOT NULL,email text NOT NULL,company text NOT NULL,message text NOT NULL,status text NOT NULL DEFAULT 'new',created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE "user" ADD COLUMN mfa_enrolled_at timestamptz;
CREATE FUNCTION record_mfa_enrollment() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW."twoFactorEnabled" AND NOT OLD."twoFactorEnabled" THEN NEW.mfa_enrolled_at=clock_timestamp(); ELSIF NOT NEW."twoFactorEnabled" THEN NEW.mfa_enrolled_at=NULL; END IF; RETURN NEW; END $$;
CREATE TRIGGER user_mfa_enrollment BEFORE UPDATE OF "twoFactorEnabled" ON "user" FOR EACH ROW EXECUTE FUNCTION record_mfa_enrollment();
